<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $interests = function_exists( 'sd_core_available_interests' ) ? sd_core_available_interests() : array(); if ( ! $interests ) { return; } ?><div class="sd-interest-filters"><span class="sd-filter-label"><?php esc_html_e( 'Interest', 'social-discovery' ); ?></span><div class="sd-interest-filter-list"><?php foreach ( $interests as $interest ) : ?><a class="sd-pill <?php echo isset( $_GET['interest'] ) && sanitize_text_field( wp_unslash( $_GET['interest'] ) ) === $interest ? 'is-active' : ''; ?>" href="<?php echo esc_url( add_query_arg( 'interest', rawurlencode( $interest ) ) ); ?>"><?php echo esc_html( $interest ); ?></a><?php endforeach; ?></div></div>
